<script setup>
import {computed,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {COLLEGES} from '../data/seed'
import Icon from '../components/Icon.vue'
const auth=useAuthStore(),market=useMarketStore(),route=useRoute(),router=useRouter()
const register=computed(()=>route.path==='/register'),busy=ref(false),error=ref('')
const form=reactive({username:'',password:'',displayName:'',college:COLLEGES[0],confirm:''})
function fill(username){form.username=username;form.password=username==='admin'?'Admin2027!':'Demo2027!';error.value=''}
async function submit(){error.value='';if(register.value&&form.password!==form.confirm){error.value='两次密码不一致，请再确认一下';return}busy.value=true;try{if(register.value)await auth.register(form);else await auth.login(form);await market.setProfile(auth.user);const target=String(route.query.redirect||'');router.replace(target.startsWith('/')&&!target.startsWith('//')?target:auth.user.role==='admin'?'/admin':'/profile')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-width auth-page"><section class="auth-art"><img src="/images/garden-painting.jpg" alt="粉色云霞风景油画"/><div class="auth-art-copy"><span class="eyebrow">A NEW CHAPTER BEGINS</span><h1>有些喜欢，<br>值得被传下去。</h1><p>属于濂溪同学的校园旧物市集<br>让每一件好物，都有温柔的下一站。</p><span class="auth-signature">See you around campus.</span></div></section><section class="auth-form-wrap"><div class="auth-form-head"><span class="eyebrow">WELCOME TO ZHAO GUI SU</span><h2>{{register?'一起，为美好找归宿。':'好久不见，欢迎回家。'}}</h2><p>{{register?'用一个账号，开启你的校园循环之旅。':'登录后，继续你的校园好物之旅。'}}</p></div><form @submit.prevent="submit" class="auth-form"><label for="username">用户名<input id="username" v-model="form.username" required :pattern="register?'[a-zA-Z0-9_]{3,24}':undefined" autocomplete="username" placeholder="请输入用户名" maxlength="24"/></label><small v-if="register" class="field-hint">3–24 位字母、数字或下划线</small><template v-if="register"><label for="display-name">你的昵称<input id="display-name" v-model="form.displayName" required maxlength="20" placeholder="希望同学怎么称呼你" autocomplete="nickname"/></label><label for="college">所在学院<select id="college" v-model="form.college"><option v-for="college in COLLEGES" :key="college">{{college}}</option></select></label></template><label for="password">密码<input id="password" v-model="form.password" type="password" required :minlength="register?8:1" :autocomplete="register?'new-password':'current-password'" placeholder="请输入密码"/></label><label v-if="register" for="confirm-password">确认密码<input id="confirm-password" v-model="form.confirm" required minlength="8" type="password" autocomplete="new-password" placeholder="再输入一次密码"/></label><p v-if="error" class="form-error" role="alert"><Icon name="info" :size="16"/>{{error}}</p><button class="button primary large full" :disabled="busy">{{busy?'请稍候…':register?'注册，加入找归宿':'登录，继续相遇'}}<Icon name="arrow" :size="18"/></button><p class="auth-switch">{{register?'已经有账号了？':'第一次来到这里？'}}<RouterLink :to="{path:register?'/login':'/register',query:route.query}">{{register?'去登录':'创建一个账号'}}<Icon name="chevron" :size="14"/></RouterLink></p></form><details v-if="!register" class="demo-accounts"><summary>课堂演示账号<Icon name="down" :size="14"/></summary><p>选择账号填入后，点击登录。</p><div><button type="button" @click="fill('student01')">林小满 · 学生</button><button type="button" @click="fill('student02')">陈知夏 · 学生</button><button type="button" @click="fill('admin')">市集管理员</button></div><small>学生密码 Demo2027! · 管理员 Admin2027!</small></details><p class="auth-bottom"><Icon name="shield" :size="15"/>江西职业技术大学 · 濂溪校区 · 2027 毕业季</p></section></div></template>
